            int mid = (lo + hi) / 2;
            int row = mid / n, col = mid % n;             // convert virtual index to (row, col)
            int val = matrix[row][col];
            if (val == target) return true;
            if (val < target) lo = mid + 1;
            else hi = mid - 1;
        }
        return false;
    }
}

